pub(crate) fn forge_text(cwd: &Path, cid: &str, name: &str, replacement: &str) -> String {
    forge_value(cwd, cid, name, Value::Text(replacement.to_owned()))
}

pub(crate) fn forge_observed_process_identity(cwd: &Path, cid: &str) -> String {
    forge_value(
        cwd,
        cid,
        "observed_process_image_cids",
        Value::List(vec![Value::Ref(cid.to_owned())]),
    )
}

pub(crate) fn forge_value(cwd: &Path, cid: &str, name: &str, replacement: Value) -> String {
    let store = ObjectStore::open(cwd);
    let Node::Value(Value::Map(mut entries)) =
        decode_node(&store.get_canonical(cid).unwrap()).unwrap()
    else {
        panic!("failure receipt must be a value map")
    };
    entries
        .iter_mut()
        .find(|(key, _)| key == &Value::Text(name.to_owned()))
        .unwrap()
        .1 = replacement;
    store
        .put_canonical(&encode_value_node(&Value::Map(entries)).unwrap())
        .unwrap()
}

