fn read_explicit_descriptor(store: &ObjectStore, cid: &str) -> Result<Vec<u8>, &'static str> {
    let path = store
        .path_for(cid)
        .map_err(|_| "explicit descriptor CID is invalid")?;
    let file = File::open(path).map_err(|_| "explicit descriptor object is unavailable")?;
    let read_limit = MAX_DESCRIPTOR_BYTES + 1;
    let mut bytes = Vec::with_capacity(read_limit);
    file.take(read_limit as u64)
        .read_to_end(&mut bytes)
        .map_err(|_| "explicit descriptor object could not be read")?;
    if bytes.len() > MAX_DESCRIPTOR_BYTES {
        return Err("explicit descriptor object exceeds the canonical byte limit");
    }
    Ok(bytes)
